import React from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import AppLayout from './components/layout/AppLayout';
import Home from './pages/Home';
import Visualization2D from './pages/visualization/Visualization2D';
import Visualization3D from './pages/visualization/Visualization3D';
import Agriculture from './pages/agriculture/Agriculture';
import DataManagement from './pages/data/DataManagement';
import { ConfigProvider } from 'antd';
import zhCN from 'antd/locale/zh_CN';

const App: React.FC = () => {
  // Determine base path based on hostname
  // If hosted on GitHub Pages, the path is /Jinhua_Weather/
  // Otherwise (local dev), it's /
  const basename = import.meta.env.PROD ? '/Jinhua_Weather/' : '/';

  return (
    <ConfigProvider locale={zhCN}>
      <BrowserRouter basename={basename}>
        <Routes>
          <Route path="/" element={<AppLayout />}>
            <Route index element={<Home />} />
            <Route path="visualization/2d" element={<Visualization2D />} />
            <Route path="visualization/3d" element={<Visualization3D />} />
            <Route path="agriculture" element={<Agriculture />} />
            <Route path="data-management" element={<DataManagement />} />
          </Route>
        </Routes>
      </BrowserRouter>
    </ConfigProvider>
  );
};

export default App;
