import React, { useState, useEffect } from 'react';
import { Card, Row, Col, Typography, Spin, theme } from 'antd';
import ReactECharts from 'echarts-for-react';
import axios from 'axios';
import * as echarts from 'echarts';

const { Title, Text } = Typography;

// Mock data for Jinhua districts
const districts = [
  { name: '婺城区', center: [119.5, 29.05], crop: '水稻', weather: 'sun' },
  { name: '金东区', center: [119.7, 29.1], crop: '蔬菜', weather: 'cloud' },
  { name: '兰溪市', center: [119.48, 29.25], crop: '杨梅', weather: 'rain' },
  { name: '义乌市', center: [120.06, 29.3], crop: '小麦', weather: 'sun' },
  { name: '东阳市', center: [120.23, 29.28], crop: '玉米', weather: 'cloud' },
  { name: '永康市', center: [120.02, 28.9], crop: '五金', weather: 'rain' }, // Crop placeholder
  { name: '武义县', center: [119.8, 28.88], crop: '茶叶', weather: 'sun' },
  { name: '浦江县', center: [119.88, 29.45], crop: '葡萄', weather: 'cloud' },
  { name: '磐安县', center: [120.45, 29.05], crop: '药材', weather: 'rain' },
];

const Agriculture: React.FC = () => {
  const [geoJson, setGeoJson] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const { token } = theme.useToken();

  useEffect(() => {
    const fetchGeo = async () => {
      try {
        const response = await axios.get('https://geo.datav.aliyun.com/areas_v3/bound/330700_full.json');
        echarts.registerMap('jinhua', response.data);
        setGeoJson(response.data);
      } catch (e) {
        console.error(e);
      } finally {
        setLoading(false);
      }
    };
    fetchGeo();
  }, []);

  const getWeatherIcon = (weather: string) => {
    // Simple SVG paths or emojis
    if (weather === 'sun') return 'path://M12 2v2m0 16v2M4.93 4.93l1.41 1.41m11.32 11.32l1.41 1.41M2 12h2m16 0h2M6.34 17.66l-1.41 1.41M19.07 4.93l-1.41 1.41M12 7a5 5 0 1 1 0 10 5 5 0 0 1 0-10z'; // Sun
    if (weather === 'cloud') return 'path://M17 17a5 5 0 0 0 2-9.9 5 5 0 0 0-9.8-1 4.5 4.5 0 0 0-4.2 4.9 5 5 0 0 0 5 6h7z'; // Cloud
    if (weather === 'rain') return 'path://M17 17a5 5 0 0 0 2-9.9 5 5 0 0 0-9.8-1 4.5 4.5 0 0 0-4.2 4.9 5 5 0 0 0 5 6h7zM10 19l-2 4m6-4l-2 4m6-4l-2 4'; // Rain
    return 'circle';
  };

  const getOption = () => {
    if (!geoJson) return {};

    return {
      backgroundColor: '#100c2a', // Tech dark background
      title: {
        text: '金华市农业气象监测',
        left: 'center',
        textStyle: { color: '#fff', fontSize: 24 }
      },
      tooltip: {
        trigger: 'item',
        formatter: '{b}'
      },
      geo: {
        map: 'jinhua',
        roam: true,
        label: {
          show: true,
          color: '#fff'
        },
        itemStyle: {
          areaColor: '#2a3359',
          borderColor: '#40c5f1',
          borderWidth: 1.5,
          shadowColor: 'rgba(64, 197, 241, 0.5)',
          shadowBlur: 10
        },
        emphasis: {
          itemStyle: {
            areaColor: '#3a4b85'
          }
        }
      },
      series: [
        // Weather Icons
        {
          name: '天气',
          type: 'scatter',
          coordinateSystem: 'geo',
          data: districts.map(d => ({
            name: d.name,
            value: [...d.center, d.weather],
            symbol: getWeatherIcon(d.weather),
            itemStyle: {
              color: d.weather === 'sun' ? '#ffeb3b' : d.weather === 'rain' ? '#4fc3f7' : '#fff'
            }
          })),
          symbolSize: 30,
          label: { show: false },
          zlevel: 2
        },
        // Crops (Effect Scatter for dynamic feel)
        {
          name: '作物',
          type: 'effectScatter',
          coordinateSystem: 'geo',
          data: districts.map(d => ({
            name: `${d.crop} (生长良好)`,
            value: [d.center[0] + 0.05, d.center[1] - 0.05, 100] // Offset slightly
          })),
          symbolSize: 15,
          showEffectOn: 'render',
          rippleEffect: {
            brushType: 'stroke',
            scale: 3
          },
          itemStyle: {
            color: '#66bb6a',
            shadowBlur: 10,
            shadowColor: '#333'
          },
          label: {
            show: true,
            formatter: '{b}',
            position: 'right',
            color: '#a5d6a7',
            fontSize: 12
          },
          zlevel: 1
        }
      ]
    };
  };

  return (
    <div className="h-full flex flex-col bg-[#100c2a] text-white p-4">
      <Row gutter={[16, 16]} className="h-full">
        <Col span={18} className="h-full relative">
          {loading ? (
             <div className="absolute inset-0 flex items-center justify-center">
                <Spin size="large" />
             </div>
          ) : (
            <ReactECharts option={getOption()} style={{ height: '100%', width: '100%' }} />
          )}
          
          {/* Overlay Info Panel */}
          <div className="absolute top-4 left-4 bg-black/50 p-4 rounded backdrop-blur-sm border border-blue-500/30">
            <Title level={4} style={{ color: '#fff', margin: 0 }}>实时监测数据</Title>
            <div className="mt-2 text-blue-200">
              <div>平均温度: 24°C</div>
              <div>平均湿度: 65%</div>
              <div>光照强度: 强</div>
            </div>
          </div>
        </Col>
        
        <Col span={6} className="h-full overflow-auto">
          <Card title={<span className="text-white">区域详情</span>} bordered={false} className="bg-[#1e2235] h-full border-blue-900/50">
            {districts.map(d => (
              <div key={d.name} className="mb-4 p-3 bg-[#2a3045] rounded border border-gray-700 hover:border-blue-500 transition-colors">
                <div className="flex justify-between items-center mb-1">
                  <Text strong className="text-lg text-blue-300">{d.name}</Text>
                  <Text className="text-gray-400">{d.weather === 'sun' ? '☀️' : d.weather === 'rain' ? '🌧️' : '☁️'}</Text>
                </div>
                <div className="text-gray-300 text-sm">
                  <div>主要作物: <span className="text-green-400">{d.crop}</span></div>
                  <div>生长状态: <span className="text-green-400">良好</span></div>
                  <div>预计产量: <span className="text-yellow-400">High</span></div>
                </div>
              </div>
            ))}
          </Card>
        </Col>
      </Row>
    </div>
  );
};

export default Agriculture;
