import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import App from './App'
import './index.css'

// Set Cesium Base URL for GitHub Pages
// vite-plugin-cesium copies assets to 'cesium' folder in dist
// We need to point Cesium to that folder with the correct base path
if (import.meta.env.PROD) {
  (window as any).CESIUM_BASE_URL = '/Jinhua_Weather/cesium/';
}

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <App />
  </StrictMode>,
)
