import { WeatherStation } from '../types';

// 金华市范围：119.2-120.8 E, 28.5-29.5 N
const JINHUA_BOUNDS = {
  minLon: 119.2,
  maxLon: 120.8,
  minLat: 28.5,
  maxLat: 29.5
};

const generateRandomStations = (count: number): WeatherStation[] => {
  const stations: WeatherStation[] = [];
  for (let i = 0; i < count; i++) {
    stations.push({
      id: `station-${i}`,
      name: `站点-${i + 1}`,
      latitude: JINHUA_BOUNDS.minLat + Math.random() * (JINHUA_BOUNDS.maxLat - JINHUA_BOUNDS.minLat),
      longitude: JINHUA_BOUNDS.minLon + Math.random() * (JINHUA_BOUNDS.maxLon - JINHUA_BOUNDS.minLon),
      elevation: Math.random() * 1000,
      data: {
        temperature: 15 + Math.random() * 15, // 15-30°C
        precipitation: Math.random() > 0.7 ? Math.random() * 50 : 0, // 30% chance of rain
        windSpeed: Math.random() * 10,
        windDirection: Math.random() * 360,
        humidity: 40 + Math.random() * 60,
        timestamp: new Date().toISOString()
      }
    });
  }
  return stations;
};

export const MOCK_STATIONS = generateRandomStations(50);

export const getWeatherStations = async (): Promise<WeatherStation[]> => {
  // Simulate API delay
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve(MOCK_STATIONS);
    }, 500);
  });
};
