import React, { useEffect, useState } from 'react';
import ReactECharts from 'echarts-for-react';
import { Radio, Space, Switch, Spin } from 'antd';
import { getWeatherStations } from '../../services/mockData';
import { WeatherStation, WeatherType } from '../../types';
import * as echarts from 'echarts';
import axios from 'axios';
import * as turf from '@turf/turf';

const Visualization2D: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [stations, setStations] = useState<WeatherStation[]>([]);
  const [dataType, setDataType] = useState<WeatherType>('temperature');
  const [showScatter, setShowScatter] = useState(true);
  const [geoJson, setGeoJson] = useState<any>(null);
  const [isobands, setIsobands] = useState<any>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const data = await getWeatherStations();
        setStations(data);
        
        // Fetch Jinhua GeoJSON
        const response = await axios.get('https://geo.datav.aliyun.com/areas_v3/bound/330700_full.json');
        echarts.registerMap('jinhua', response.data);
        setGeoJson(response.data);
      } catch (error) {
        console.error('Failed to load data', error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  // Generate Isobands when stations or dataType changes
  useEffect(() => {
    if (!stations.length || !geoJson) return;

    try {
      // 1. Prepare points for Turf
      const points = turf.featureCollection(
        stations.map(s => {
          let value = 0;
          switch (dataType) {
            case 'temperature': value = s.data.temperature || 0; break;
            case 'precipitation': value = s.data.precipitation || 0; break;
            case 'wind': value = s.data.windSpeed || 0; break;
            case 'humidity': value = s.data.humidity || 0; break;
          }
          return turf.point([s.longitude, s.latitude], { value });
        })
      );

      // 2. IDW Interpolation
      // Jinhua bounds: ~119.2 to 120.8, ~28.5 to 29.5
      // Create a grid of points
      const cellSide = 0.05; // Finer resolution for better look
      const options: any = { gridType: 'points', property: 'value', units: 'degrees' }; 
      // Note: 'point' or 'points' depending on turf version, usually 'point' in @turf/interpolate
      // But let's use default if possible or check docs. @turf/turf 7.x
      
      const grid = turf.interpolate(points, cellSide, {
        gridType: 'point',
        property: 'value',
        units: 'degrees'
      });

      // 3. Generate Isobands (Contours)
      // Define breaks based on data type
      let breaks = [0, 10, 20, 30, 40];
      if (dataType === 'temperature') breaks = [0, 5, 10, 15, 20, 25, 30, 35, 40, 45];
      else if (dataType === 'precipitation') breaks = [0, 10, 25, 50, 100, 250];
      else if (dataType === 'humidity') breaks = [0, 20, 40, 60, 80, 100];
      else if (dataType === 'wind') breaks = [0, 2, 4, 6, 8, 10, 12, 15];

      const bands = turf.isobands(grid as any, breaks, { zProperty: 'value' });
      
      setIsobands(bands);
    } catch (error) {
      console.error("Interpolation error:", error);
    }

  }, [stations, dataType, geoJson]);

  const getOption = () => {
    if (!stations.length || !geoJson) return {};

    const scatterData = stations.map(s => {
      let value = 0;
      switch (dataType) {
        case 'temperature': value = s.data.temperature || 0; break;
        case 'precipitation': value = s.data.precipitation || 0; break;
        case 'wind': value = s.data.windSpeed || 0; break;
        case 'humidity': value = s.data.humidity || 0; break;
      }
      return {
        name: s.name,
        value: [s.longitude, s.latitude, value]
      };
    });

    // Transform Isobands to ECharts Polygon Series
    const contourSeries = isobands && isobands.features ? isobands.features.map((feature: any, index: number) => {
      const coordinates = feature.geometry.coordinates;
      const type = feature.geometry.type;
      
      // Handle MultiPolygon vs Polygon
      // ECharts custom renderItem needs consistent logic.
      // Polygon: [[x,y], [x,y]...] (Ring) inside Array of Rings: [[[x,y]...], [[x,y]...]]
      // MultiPolygon: Array of Polygons: [ [[[x,y]...]], ... ]
      
      const polygons = type === 'MultiPolygon' ? coordinates : [coordinates];
      
      // Determine color based on value range
      const valueStr = feature.properties.value; // "0-10"
      const lowerBound = parseFloat(valueStr.split('-')[0]);
      const color = getColor(lowerBound, dataType);
      
      return {
        type: 'custom',
        coordinateSystem: 'geo',
        renderItem: (params: any, api: any) => {
          let children = [];
          
          for (let poly of polygons) {
             // Each poly is an array of rings (outer ring + holes)
             // ECharts 'polygon' shape takes 'points' for one ring? 
             // Or 'paths'? 
             // Actually, ECharts polygon shape supports holes if we pass array of rings?
             // No, standard 'polygon' shape in custom series usually takes a single list of points.
             // But we can draw complex paths.
             // For simplicity, let's just draw the outer ring (index 0).
             // IDW usually produces simple polygons, but holes are possible.
             
             // If we want to support holes, we need to use 'path' shape with SVG path data string.
             // OR use multiple 'polygon' shapes but that doesn't subtract holes.
             
             // Let's assume the first ring is the outer ring and just draw that for now to avoid complexity.
             // Wait, isobands often have holes.
             // ECharts 'polygon' shape documentation: shape: { points: [...] }
             // It doesn't seem to support holes easily in 'custom' series 'polygon' type.
             // However, 'path' shape allows d="M... L... Z M... L... Z" which supports holes (evenodd rule).
             
             // Let's try to construct an SVG path.
             let pathData = '';
             for (let ring of poly) {
                // ring is array of [x, y]
                for (let i = 0; i < ring.length; i++) {
                    const coord = api.coord(ring[i]);
                    if (i === 0) pathData += `M${coord[0]} ${coord[1]}`;
                    else pathData += `L${coord[0]} ${coord[1]}`;
                }
                pathData += 'Z ';
             }
             
             children.push({
                type: 'path',
                shape: {
                    d: pathData
                },
                style: api.style({
                    fill: color,
                    stroke: 'none',
                    opacity: 0.7 // Semi-transparent to see base map details
                })
             });
          }
          
          return {
             type: 'group',
             children: children
          };
        },
        data: [0], 
        zlevel: 1,
        silent: true // Disable mouse events on contours to let scatter points be clickable
      };
    }) : [];

    return {
      title: {
        text: `金华市气象要素分布 - ${dataType === 'temperature' ? '温度' : dataType === 'precipitation' ? '降水' : dataType === 'wind' ? '风速' : '湿度'}`,
        left: 'center',
        top: 10
      },
      tooltip: {
        trigger: 'item',
        formatter: (params: any) => {
          if (params.seriesType === 'scatter') {
             return `${params.name}<br/>${dataType}: ${params.value[2].toFixed(1)}`;
          }
          return '';
        }
      },
      geo: {
        map: 'jinhua',
        roam: true,
        label: { show: true, color: '#666' },
        itemStyle: {
          areaColor: '#fff', // White basemap as requested
          borderColor: '#999',
          borderWidth: 1
        },
        emphasis: {
          itemStyle: { areaColor: '#f0f0f0' }
        },
        zlevel: 0
      },
      series: [
        ...contourSeries,
        showScatter && {
          name: '站点',
          type: 'scatter',
          coordinateSystem: 'geo',
          data: scatterData,
          symbolSize: 8,
          itemStyle: {
            color: '#333',
            borderColor: '#fff',
            borderWidth: 1
          },
          zlevel: 2
        }
      ].filter(Boolean)
    };
  };

  const getColor = (value: number, type: string) => {
    // Simple colormap
    const colors = type === 'temperature' 
      ? ['#313695', '#4575b4', '#74add1', '#abd9e9', '#e0f3f8', '#ffffbf', '#fee090', '#fdae61', '#f46d43', '#d73027', '#a50026']
      : ['#f7fbff', '#deebf7', '#c6dbef', '#9ecae1', '#6baed6', '#4292c6', '#2171b5', '#08519c', '#08306b'];
    
    let max = type === 'temperature' ? 40 : 100;
    let index = Math.floor((value / max) * colors.length);
    index = Math.max(0, Math.min(index, colors.length - 1));
    return colors[index];
  };

  return (
    <div className="h-full flex flex-col">
      <div className="mb-4 flex justify-between items-center bg-white p-4 rounded shadow-sm">
        <Space size="large">
          <div>
            <span className="mr-2 font-bold">要素类型:</span>
            <Radio.Group value={dataType} onChange={e => setDataType(e.target.value)}>
              <Radio.Button value="temperature">温度</Radio.Button>
              <Radio.Button value="precipitation">降水</Radio.Button>
              <Radio.Button value="wind">风速</Radio.Button>
              <Radio.Button value="humidity">湿度</Radio.Button>
            </Radio.Group>
          </div>
          <div>
            <span className="mr-2">显示站点:</span>
            <Switch checked={showScatter} onChange={setShowScatter} />
          </div>
        </Space>
      </div>

      <div className="flex-1 bg-white rounded shadow-sm p-4 relative">
        {loading ? (
          <div className="absolute inset-0 flex items-center justify-center">
            <Spin size="large" tip="加载地图数据中..." />
          </div>
        ) : (
          <ReactECharts 
            option={getOption()} 
            style={{ height: '100%', width: '100%' }}
            notMerge={true}
          />
        )}
      </div>
    </div>
  );
};

export default Visualization2D;
