import React, { useEffect, useRef, useState } from 'react';
import { Viewer, Entity, ParticleSystem, ImageryLayer } from 'resium';
import * as Cesium from 'cesium';
import { Radio, Space, Switch, Button } from 'antd';
import { getWeatherStations } from '../../services/mockData';
import { WeatherStation, WeatherType } from '../../types';

// Use standard OSM imagery which typically doesn't require a special token for basic usage
const imageryProvider = new Cesium.OpenStreetMapImageryProvider({
  url: 'https://a.tile.openstreetmap.org/'
});

const Visualization3D: React.FC = () => {
  const viewerRef = useRef<any>(null);
  const [stations, setStations] = useState<WeatherStation[]>([]);
  const [dataType, setDataType] = useState<WeatherType>('temperature');
  const [showTerrain, setShowTerrain] = useState(false);
  const [effect, setEffect] = useState<'none' | 'rain' | 'snow'>('none');

  const [particleCanvas, setParticleCanvas] = useState<HTMLCanvasElement | null>(null);

  useEffect(() => {
    // Create a simple particle image (soft white circle)
    const canvas = document.createElement('canvas');
    canvas.width = 32;
    canvas.height = 32;
    const context = canvas.getContext('2d');
    if (context) {
      const gradient = context.createRadialGradient(16, 16, 0, 16, 16, 16);
      gradient.addColorStop(0, 'rgba(255, 255, 255, 1)');
      gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');
      context.fillStyle = gradient;
      context.fillRect(0, 0, 32, 32);
      setParticleCanvas(canvas);
    }
  }, []);

  useEffect(() => {
    getWeatherStations().then(setStations);
  }, []);

  useEffect(() => {
    if (viewerRef.current && viewerRef.current.cesiumElement) {
      const viewer = viewerRef.current.cesiumElement;
      
      // Load Jinhua GeoJSON
      Cesium.GeoJsonDataSource.load('https://geo.datav.aliyun.com/areas_v3/bound/330700_full.json', {
        stroke: Cesium.Color.YELLOW,
        fill: Cesium.Color.BLUE.withAlpha(0.1),
        strokeWidth: 3
      }).then((dataSource) => {
        viewer.dataSources.add(dataSource);
        viewer.zoomTo(dataSource);
      }).catch(error => {
        console.error("Error loading GeoJSON:", error);
      });

      // Fly to Jinhua (fallback if zoomTo fails or for initial view)
      viewer.camera.flyTo({
        destination: Cesium.Cartesian3.fromDegrees(119.65, 29.08, 200000),
        orientation: {
          heading: 0.0,
          pitch: -Cesium.Math.PI_OVER_TWO,
          roll: 0.0
        }
      });
    }
  }, [viewerRef.current]);

  const getColor = (value: number, type: WeatherType) => {
    if (type === 'temperature') {
      if (value > 35) return Cesium.Color.RED;
      if (value > 25) return Cesium.Color.ORANGE;
      if (value > 15) return Cesium.Color.YELLOW;
      return Cesium.Color.BLUE;
    }
    if (type === 'precipitation') {
      if (value > 50) return Cesium.Color.DARKBLUE;
      if (value > 10) return Cesium.Color.BLUE;
      return Cesium.Color.LIGHTBLUE;
    }
    return Cesium.Color.WHITE;
  };

  const getParticleSystem = () => {
    if (effect === 'none' || !particleCanvas) return null;
    
    const isRain = effect === 'rain';
    
    return (
      <ParticleSystem
        image={particleCanvas}
        startColor={isRain ? new Cesium.Color(0.8, 0.8, 1.0, 0.5) : new Cesium.Color(1.0, 1.0, 1.0, 0.8)}
        endColor={isRain ? new Cesium.Color(0.8, 0.8, 1.0, 0.0) : new Cesium.Color(1.0, 1.0, 1.0, 0.0)}
        startScale={isRain ? 1.0 : 4.0}
        endScale={isRain ? 1.0 : 4.0}
        minimumParticleLife={1.5}
        maximumParticleLife={2.0}
        minimumSpeed={isRain ? 15.0 : 2.0}
        maximumSpeed={isRain ? 20.0 : 4.0}
        imageSize={isRain ? new Cesium.Cartesian2(4, 15) : new Cesium.Cartesian2(10, 10)}
        emissionRate={isRain ? 200.0 : 100.0}
        lifetime={10.0}
        emitter={new Cesium.SphereEmitter(50000.0)} // Large area emitter
        modelMatrix={Cesium.Transforms.eastNorthUpToFixedFrame(
          Cesium.Cartesian3.fromDegrees(119.65, 29.08, 1000)
        )}
      />
    );
  };

  return (
    <div className="h-full flex flex-col relative">
      <div className="absolute top-4 left-4 z-10 bg-white p-4 rounded shadow-md opacity-90">
        <Space direction="vertical">
          <div>
            <span className="mr-2 font-bold">要素类型:</span>
            <Radio.Group value={dataType} onChange={e => setDataType(e.target.value)} size="small">
              <Radio.Button value="temperature">温度</Radio.Button>
              <Radio.Button value="precipitation">降水</Radio.Button>
            </Radio.Group>
          </div>
          <div>
            <span className="mr-2">地形开关:</span>
            <Switch checked={showTerrain} onChange={setShowTerrain} />
          </div>
          <div>
            <span className="mr-2">动态效果:</span>
            <Radio.Group value={effect} onChange={e => setEffect(e.target.value)} size="small">
              <Radio.Button value="none">无</Radio.Button>
              <Radio.Button value="rain">雨</Radio.Button>
              <Radio.Button value="snow">雪</Radio.Button>
            </Radio.Group>
          </div>
        </Space>
      </div>

      <div className="flex-1 relative h-full">
        <Viewer 
          full
          ref={viewerRef}
          baseLayerPicker={false} // Disable default picker
          terrainProvider={showTerrain ? undefined : undefined} // Keep disabled if no token
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            height: '100%'
          }}
        >
          <ImageryLayer imageryProvider={imageryProvider} />
          {stations.map(station => {
            const value = dataType === 'temperature' ? station.data.temperature : station.data.precipitation;
            if (value === undefined) return null;

            return (
              <Entity
                key={station.id}
                name={station.name}
                position={Cesium.Cartesian3.fromDegrees(station.longitude, station.latitude, (station.elevation || 0) + 100)}
                point={{ 
                  pixelSize: 15, 
                  color: getColor(value, dataType),
                  outlineColor: Cesium.Color.BLACK,
                  outlineWidth: 2
                }}
                description={`
                  <h3>${station.name}</h3>
                  <p>经度: ${station.longitude.toFixed(4)}</p>
                  <p>纬度: ${station.latitude.toFixed(4)}</p>
                  <p>${dataType === 'temperature' ? '温度' : '降水'}: ${value.toFixed(1)}</p>
                `}
              />
            );
          })}
          
          {getParticleSystem()}
        </Viewer>
      </div>
    </div>
  );
};

export default Visualization3D;
